# Expected values are SymPy's outputs for the same calls (Vectors (sympy.vector)).

skip_on_cran()

x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z")
a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); q <- Symbol("q")
q0 <- Symbol("q0"); q1 <- Symbol("q1"); q2 <- Symbol("q2"); q3 <- Symbol("q3"); q4 <- Symbol("q4"); q5 <- Symbol("q5")
u <- Symbol("u"); v <- Symbol("v"); r <- Symbol("r"); s <- Symbol("s"); t <- Symbol("t")
theta <- Symbol("theta"); phi <- Symbol("phi"); alpha <- Symbol("alpha")
f <- Function("f")
pi <- sym_pi; E <- sym_E; I <- sym_I
C <- CoordSys3D("C"); i <- C$i; j <- C$j; k <- C$k
V1 <- C$x * i + C$z * C$z * j
V2 <- C$x * i + C$y * j + C$z * k
N <- CoordSys3D("N")
A <- orient_new_axis(N, "A", q1, N$k)
B <- orient_new_axis(A, "B", q2, A$i)
Cn <- orient_new_axis(B, "C", q3, B$j)
R <- CoordSys3D("R")
P <- orient_new_axis(C, "P", q, C$k)
delop <- Del()
True <- TRUE; False <- FALSE

test_that("Vectors (sympy.vector) match SymPy", {
  expect_equal(.pyfmt(Cross(V1, V2)), "Cross(C.x*C.i + C.z^2*C.j, C.x*C.i + C.y*C.j + C.z*C.k)")
  expect_equal(.pyfmt(doit(Cross(V1, V2))), "C.z^3*C.i + (-C.x*C.z)*C.j + (C.x*C.y - C.x*C.z^2)*C.k")
  expect_equal(.pyfmt(cross(V1, V2)), "C.z^3*C.i + (-C.x*C.z)*C.j + (C.x*C.y - C.x*C.z^2)*C.k")
  expect_equal(.pyfmt(Cross(V2, V1)), "-Cross(C.x*C.i + C.z^2*C.j, C.x*C.i + C.y*C.j + C.z*C.k)")
  expect_equal(.pyfmt(Cross(V1, V2) == -Cross(V2, V1)), "True")
  expect_equal(.pyfmt(cross(V1, V2) + cross(V2, V1)), "0")
  expect_equal(.pyfmt(Cross(V1, V2) + Cross(V2, V1)), "0")
  expect_equal(.pyfmt(Dot(V1, V2)), "Dot(C.x*C.i + C.z^2*C.j, C.x*C.i + C.y*C.j + C.z*C.k)")
  expect_equal(.pyfmt(doit(Dot(V1, V2))), "C.x^2 + C.y*C.z^2")
  expect_equal(.pyfmt(doit(Dot(V2, V1))), "C.x^2 + C.y*C.z^2")
  expect_equal(.pyfmt(Dot(V1, V2) == Dot(V2, V1)), "True")
  expect_equal(.pyfmt(Dot(V2, V1)), "Dot(C.x*C.i + C.z^2*C.j, C.x*C.i + C.y*C.j + C.z*C.k)")
  expect_equal(.pyfmt(3*j), "3*C.j")
  expect_equal(.pyfmt(j*3 == 3*j), "True")
  expect_equal(.pyfmt(components(3*j)), "{C.j: 3}")
  expect_equal(.pyfmt(3*i + 4*j + 5*k), "3*C.i + 4*C.j + 5*C.k")
  expect_equal(.pyfmt((2*i + 4*j + i + 4*k + k) == (3*i + 4*j + 5*k)), "True")
  expect_equal(.pyfmt(2*i + 4*j + i + 4*k + k), "3*C.i + 4*C.j + 5*C.k")
  expect_equal(.pyfmt(sym_type(Add(C$i, C$j))), "VectorAdd")
  expect_equal(.pyfmt(sym_type(Add(V1, V2))), "VectorAdd")
  expect_equal(.pyfmt(i != j), "True")
  expect_equal(.pyfmt(i - i), "0")
  expect_equal(.pyfmt(i + VectorZero()), "C.i")
  expect_equal(.pyfmt(i - VectorZero()), "C.i")
  expect_equal(.pyfmt(VectorZero() != 0), "True")
  expect_equal(.pyfmt(-VectorZero()), "0")
  expect_equal(.pyfmt(VectorZero() - i), "(-1)*C.i")
  expect_equal(.pyfmt((a*i + b*j + c*k) - (a*i + b*j + c*k)), "0")
  expect_equal(.pyfmt((a*i + b*j + c*k)*0.0), "0")
  expect_equal(.pyfmt((a*i + b*j + c*k) + VectorZero()), "a*C.i + b*C.j + c*C.k")
  expect_equal(.pyfmt(dot(a*i + b*j + c*k, i)), "a")
  expect_equal(.pyfmt(dot(a*i + b*j + c*k, k)), "c")
  expect_equal(.pyfmt(dot(i, a^2*i + b^2*j + c^2*k)), "a^2")
  expect_equal(.pyfmt(dot(a*i + b*j + c*k + a^2*i + b^2*j + c^2*k, i)), "a^2 + a")
  expect_equal(.pyfmt(dot(a*i + b*j + c*k + a^2*i + b^2*j + c^2*k, j)), "b^2 + b")
  expect_equal(.pyfmt(a*i + b*j + c*k + a^2*i + b^2*j + c^2*k), "(a^2 + a)*C.i + (b^2 + b)*C.j + (c^2 + c)*C.k")
  expect_equal(.pyfmt((a*i + b*j + c*k) - (a^2*i + b^2*j + c^2*k)), "(-a^2 + a)*C.i + (-b^2 + b)*C.j + (-c^2 + c)*C.k")
  expect_equal(.pyfmt((a*i + b*j + c*k) - (a^2*i + b^2*j + c^2*k) == -1 * ((a^2*i + b^2*j + c^2*k) - (a*i + b*j + c*k))), "True")
  expect_equal(.pyfmt(a * (a*i + b*j + c*k)), "a^2*C.i + a*b*C.j + a*c*C.k")
  expect_equal(.pyfmt(a * (a*i + b*j + c*k) == (a*i + b*j + c*k) * a), "True")
  expect_equal(.pyfmt(2 * (a*i + b*j + c*k)), "2*a*C.i + 2*b*C.j + 2*c*C.k")
  expect_equal(.pyfmt(sym_type(2 * (a*i + b*j + c*k))), "VectorAdd")
  expect_equal(.pyfmt(base_vector(a * i)), "C.i")
  expect_equal(.pyfmt(measure_number(a * i)), "a")
  expect_equal(.pyfmt(sym_type(a * i)), "VectorMul")
  expect_equal(.pyfmt((a*i + b*j + c*k) * 0), "0")
  expect_equal(.pyfmt(sym_type((a*i + b*j + c*k) * 0)), "VectorZero")
  expect_equal(.pyfmt(to_matrix(a*i + b*j + c*k, C)), "Matrix([[a], [b], [c]])")
  expect_equal(.pyfmt(components(i)), "{C.i: 1}")
  expect_equal(.pyfmt(components(a*i)), "{C.i: a}")
  expect_equal(.pyfmt(components(a*i + b*j + c*k)), "{C.i: a, C.j: b, C.k: c}")
  expect_equal(.pyfmt(VectorAdd(a*i + b*j + c*k, VectorZero())), "a*C.i + b*C.j + c*C.k")
  expect_equal(.pyfmt(VectorMul(a, a*i + b*j + c*k)), "a^2*C.i + a*b*C.j + a*c*C.k")
  expect_equal(.pyfmt(VectorMul(1, i)), "C.i")
  expect_equal(.pyfmt(VectorMul(0, VectorZero())), "0")
  expect_error(outer_sym(a*i + b*j + c*k, 1), "Invalid operand for outer product", fixed = TRUE)
  expect_error(dot(a*i + b*j + c*k, 1), "1 is not a vector, dyadic or del operator", fixed = TRUE)
  expect_equal(.pyfmt(magnitude(VectorZero())), "0")
  expect_equal(.pyfmt(normalize(VectorZero())), "0")
  expect_equal(.pyfmt(magnitude(i)), "1")
  expect_equal(.pyfmt(normalize(k)), "C.k")
  expect_equal(.pyfmt(normalize(a * i)), "(a/sqrt(a^2))*C.i")
  expect_equal(.pyfmt(magnitude(a * i)), "sqrt(a^2)")
  expect_equal(.pyfmt(magnitude(a*i + b*j + c*k)), "sqrt(a^2 + b^2 + c^2)")
  expect_equal(.pyfmt(normalize(a*i + b*j + c*k)), "(a/sqrt(a^2 + b^2 + c^2))*C.i + (b/sqrt(a^2 + b^2 + c^2))*C.j + (c/sqrt(a^2 + b^2 + c^2))*C.k")
  expect_equal(.pyfmt(normalize(i + j)), "(sqrt(2)/2)*C.i + (sqrt(2)/2)*C.j")
  expect_equal(.pyfmt(normalize(3*i + 4*j)), "3/5*C.i + 4/5*C.j")
  expect_equal(.pyfmt(((1 / a + 1 / b) * i) & i), "1/b + 1/a")
  expect_equal(.pyfmt(simplify((1 / a + 1 / b) * i)), "((a + b)/(a*b))*C.i")
  expect_equal(.pyfmt(simplify((1 / a + 1 / b) * i) & i), "(a + b)/(a*b)")
  expect_equal(.pyfmt(simplify((1 / a + 1 / b) * i)), "((a + b)/(a*b))*C.i")
  expect_equal(.pyfmt(simplify((a^2 * s^4 / (4 * pi * d * e^3)) * i)), "(a^2*s^4/(4*pi*d*e^3))*C.i")
  expect_equal(.pyfmt(simplify(((4 + 4 * a - 2 * (2 + 2 * a)) / (2 + 2 * a)) * i)), "0")
  expect_equal(.pyfmt(simplify(((-4 * a * b^2 - 2 * b^3 - 2 * a^2 * b) / (a + b)^2) * i)), "(-2*b)*C.i")
  expect_equal(.pyfmt(trigsimp((sin(a)+cos(a))^2*i - j)), "(2*sin(a + pi/4)^2)*C.i + (-1)*C.j")
  expect_equal(.pyfmt(trigsimp((sin(a)+cos(a))^2*i - j)), "(2*sin(a + pi/4)^2)*C.i + (-1)*C.j")
  expect_equal(.pyfmt(simplify(VectorZero())), "0")
  expect_equal(.pyfmt((sin(a)+cos(a))^2*i - j), "((sin(a) + cos(a))^2)*C.i + (-1)*C.j")
  expect_equal(.pyfmt(vector_equals(2*i, j)), "False")
  expect_equal(.pyfmt(vector_equals(i, i)), "True")
  expect_equal(.pyfmt(vector_equals(((sqrt(S(2)) + sqrt(S(6))) / sqrt(sqrt(S(3)) + 2))*i, 2*i)), "True")
  expect_equal(.pyfmt(vector_equals(((sqrt(S(2)) + sqrt(S(6))) / sqrt(sqrt(S(3)) + 2))*i, 3*i)), "False")
  expect_equal(.pyfmt({D <- orient_new_axis(C, "D", pi/2, C$k); vector_equals(D$i, C$j)}), "True")
  expect_equal(.pyfmt({D <- orient_new_axis(C, "D", pi/2, C$k); vector_equals(D$i, C$i)}), "False")
  expect_equal(.pyfmt(conjugate(I*i + (1 + I)*j + 2*k)), "(-I)*C.i + (1 - I)*C.j + 2*C.k")
  expect_equal(.pyfmt(I*i + (1 + I)*j + 2*k), "I*C.i + (1 + I)*C.j + 2*C.k")
  expect_equal(.pyfmt(dot(i, VectorZero())), "0")
  expect_equal(.pyfmt(dot(VectorZero(), i)), "0")
  expect_equal(.pyfmt(i & VectorZero()), "0")
  expect_equal(.pyfmt(dot(i, i)), "1")
  expect_equal(.pyfmt(dot(i, j)), "0")
  expect_equal(.pyfmt(i & k), "0")
  expect_equal(.pyfmt(j & j), "1")
  expect_equal(.pyfmt(dot(k, j)), "0")
  expect_equal(.pyfmt(k & k), "1")
  expect_error(dot(k, 1), "1 is not a vector, dyadic or del operator", fixed = TRUE)
  expect_equal(.pyfmt(cross(i, VectorZero())), "0")
  expect_equal(.pyfmt(cross(VectorZero(), i)), "0")
  expect_equal(.pyfmt(cross(i, i)), "0")
  expect_equal(.pyfmt(cross(i, j)), "C.k")
  expect_equal(.pyfmt(cross(i, k)), "(-1)*C.j")
  expect_equal(.pyfmt(cross(j, i)), "(-1)*C.k")
  expect_equal(.pyfmt(cross(j, k)), "C.i")
  expect_equal(.pyfmt(cross(k, i)), "C.j")
  expect_equal(.pyfmt(cross(k, j)), "(-1)*C.i")
  expect_equal(.pyfmt(cross(k, k)), "0")
  expect_equal(.pyfmt(cross(k, 1)), "-Cross(1, C.k)")
  expect_equal(.pyfmt(projection(i + j + k, i + j + k)), "C.i + C.j + C.k")
  expect_equal(.pyfmt(projection(i + j + k, 3*i + 4*j)), "7/3*C.i + 7/3*C.j + 7/3*C.k")
  expect_equal(.pyfmt(projection(i + j + k, i + j + k, scalar = TRUE)), "1")
  expect_equal(.pyfmt(projection(i + j + k, 3*i + 4*j, scalar = TRUE)), "7/3")
  expect_equal(.pyfmt(projection(0*i + 0*j, i + j + k)), "0")
  expect_equal(.pyfmt(projection(0*i + 0*j, i + j + k, scalar = TRUE)), "0")
  expect_equal(.pyfmt(Derivative(f(a)*C$i + a^2*C$j - C$k, a)), "Derivative((f(a))*C.i + a^2*C.j + (-1)*C.k, a)")
  expect_equal(.pyfmt(diff(f(a)*C$i + a^2*C$j - C$k, a)), "(Derivative(f(a), a))*C.i + 2*a*C.j")
  expect_equal(.pyfmt(doit(Derivative(f(a)*C$i + a^2*C$j - C$k, a))), "(Derivative(f(a), a))*C.i + 2*a*C.j")
  expect_equal(.pyfmt(Integral(f(a)*C$i + a^2*C$j - C$k, a)), "(Integral(f(a), a))*C.i + (Integral(a^2, a))*C.j + (Integral(-1, a))*C.k")
  expect_equal(.pyfmt(integrate(f(a)*C$i + a^2*C$j - C$k, a)), "(Integral(f(a), a))*C.i + (Integral(a^2, a))*C.j + (Integral(-1, a))*C.k")
  expect_equal(.pyfmt(integrate(a*C$i + a^2*C$j - C$k, list(a, 0, 2))), "(Integral(a, (a, 0, 2)))*C.i + (Integral(a^2, (a, 0, 2)))*C.j + (Integral(-1, (a, 0, 2)))*C.k")
  expect_error(BaseVector(3, C), "index must be 0, 1 or 2", fixed = TRUE)
  expect_error(BaseVector(0, VectorZero()), "system should be a CoordSys3D", fixed = TRUE)
  expect_error(Add(1, C$i), "1 cannot be interpreted correctly", fixed = TRUE)
  expect_error(Add(C$i, 2), "2 cannot be interpreted correctly", fixed = TRUE)
  expect_error(Add(a, C$j), "a cannot be interpreted correctly", fixed = TRUE)
  expect_error(Add(1.5, C$i), "1.50000000000000 cannot be interpreted correctly", fixed = TRUE)
  expect_error(Add(I, C$j), "I cannot be interpreted correctly", fixed = TRUE)
  expect_error(Add(Rational(3, 2), C$k), "3/2 cannot be interpreted correctly", fixed = TRUE)
  expect_equal(.pyfmt(Mul(2, C$i)), "2*C.i")
  expect_equal(.pyfmt(Mul(2, 3, C$i)), "6*C.i")
  expect_equal(.pyfmt(measure_number(Mul(2, 3, C$i))), "6")
  expect_equal(.pyfmt(Mul(x, C$i)), "x*C.i")
  expect_equal(.pyfmt(Mul(x, y, C$j)), "x*y*C.j")
  expect_equal(.pyfmt(measure_number(Mul(x, y, C$j))), "x*y")
  expect_equal(.pyfmt(Mul(-1, C$i)), "(-1)*C.i")
  expect_equal(.pyfmt(Mul(1, C$j)), "C.j")
  expect_equal(.pyfmt(Mul(Rational(3, 2), C$k)), "3/2*C.k")
  expect_error(Mul(C$i, C$j), "Invalid multiplication", fixed = TRUE)
  expect_error(Mul(C$j, C$k), "Invalid multiplication", fixed = TRUE)
  expect_equal(.pyfmt(Add(C$i, C$j)), "C.i + C.j")
  expect_equal(.pyfmt(Add(V1, V2)), "2*C.x*C.i + (C.y + C.z^2)*C.j + C.z*C.k")
  expect_equal(.pyfmt(Add(C$i, VectorZero())), "C.i")
  expect_equal(.pyfmt(Add(C$i, -C$i)), "0")
  expect_equal(.pyfmt(Add(C$i, C$i)), "2*C.i")
  expect_error(C$i^2, "Power operation is not supported for vectors", fixed = TRUE)
  expect_error((C$i + C$j)^2, "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(Mul(C$i, C$i), "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(Pow(C$i, 2), "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(Pow(C$k, -1), "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(2^C$i, "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(a^C$j, "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(Pow(2, C$k), "Power operation is not supported for vectors", fixed = TRUE)
  expect_error((2*C$k)^3, "Power operation is not supported for vectors", fixed = TRUE)
  expect_error(C$i * C$j, "Invalid multiplication", fixed = TRUE)
  expect_error(C$i / C$j, "Cannot divide two vectors", fixed = TRUE)
  expect_error(C$i / 0, "Cannot divide a vector by zero", fixed = TRUE)
  expect_equal(.pyfmt((a*C$i + C$j) / a), "C.i + 1/a*C.j")
  expect_error(C$i + 1, "1 cannot be interpreted correctly", fixed = TRUE)
  expect_error(1 + C$i, "1 cannot be interpreted correctly", fixed = TRUE)
  expect_error(C$i - 1, "-1 cannot be interpreted correctly", fixed = TRUE)
  expect_error(VectorZero() + 1, "Invalid argument types for addition", fixed = TRUE)
  expect_equal(.pyfmt(3*C$x*C$i - C$y^2*C$j), "3*C.x*C.i + (-C.y^2)*C.j")
  expect_equal(.pyfmt(-(a + b)*C$i), "(-a - b)*C.i")
  expect_equal(.pyfmt((a - b)*C$j + x/y*C$k), "(a - b)*C.j + x/y*C.k")
  expect_equal(.pyfmt(sin(x)*C$i + 2.5*C$j), "(sin(x))*C.i + 2.5*C.j")
  expect_equal(.pyfmt(C$x*C$y*C$z), "C.x*C.y*C.z")
  expect_equal(.pyfmt(C$x + a + x + C$y), "C.x + C.y + a + x")
  expect_equal(.pyfmt({cc <- CoordSys3D("c"); cc$x*a + cc$y}), "c.x*a + c.y")
  expect_equal(.pyfmt({cc <- CoordSys3D("c"); a*C$i + cc$x*C$j}), "a*C.i + c.x*C.j")
  expect_equal(.pyfmt({cc <- CoordSys3D("c"); cc$i + C$k + N$j}), "C.k + N.j + c.i")
  expect_equal(.pyfmt(Cross(C$i, 2*C$j)), "Cross(C.i, 2*C.j)")
  expect_equal(.pyfmt(Cross(2*C$j, C$i)), "-Cross(C.i, 2*C.j)")
  expect_equal(.pyfmt(Cross(C$i + C$j, a*C$k)), "-Cross(a*C.k, C.i + C.j)")
  expect_equal(.pyfmt(Dot(C$k, C$i)), "Dot(C.i, C.k)")
  expect_equal(.pyfmt(Dot(C$i + C$k, C$j)), "Dot(C.j, C.i + C.k)")
  expect_equal(.pyfmt(VectorZero()), "0")
  expect_equal(.pyfmt(N$i), "N.i")
  expect_equal(.pyfmt(-N$i), "(-1)*N.i")
  expect_equal(.pyfmt(N$i + N$j), "N.i + N.j")
  expect_equal(.pyfmt(a*N$i), "a*N.i")
  expect_equal(.pyfmt(a*N$i - b*N$j), "a*N.i + (-b)*N.j")
  expect_equal(.pyfmt((a^2 + N$x)*N$i + N$k), "(N.x + a^2)*N.i + N.k")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); (a^2 + b)*N$i + 3*(Cp$y - c)*N$k}), "(a^2 + b)*N.i + (3*C.y - 3*c)*N.k")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); N$j - (Integral(f(b)) - Cp$x^2)*N$k}), "N.j + (C.x^2 - Integral(f(b), b))*N.k")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); N$i + Cp$k}), "C.k + N.i")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); express(N$i, Cp)}), "(cos(a))*C.i + (-sin(a))*C.j")
  expect_equal(.pyfmt((a^2 + b)*N$i + (Integral(f(b)))*N$k), "(a^2 + b)*N.i + (Integral(f(b), b))*N.k")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); 3*N$x^2*Cp$y}), "3*C.y*N.x^2")
  expect_equal(.pyfmt(VectorZero() | N$k), "0")
  expect_equal(.pyfmt(N$i | N$k), "(N.i|N.k)")
  expect_equal(.pyfmt(-N$i | N$k), "(-1)*(N.i|N.k)")
  expect_equal(.pyfmt((N$i + N$j) | N$k), "(N.i|N.k) + (N.j|N.k)")
  expect_equal(.pyfmt((a*N$i) | N$k), "a*(N.i|N.k)")
  expect_equal(.pyfmt((a*N$i - b*N$j) | N$k), "a*(N.i|N.k) + (-b)*(N.j|N.k)")
  expect_equal(.pyfmt(((a^2 + N$x)*N$i + N$k) | N$k), "(N.x + a^2)*(N.i|N.k) + (N.k|N.k)")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); (N$j - (Integral(f(b)) - Cp$x^2)*N$k) | N$k}), "(N.j|N.k) + (C.x^2 - Integral(f(b), b))*(N.k|N.k)")
  expect_equal(.pyfmt({Cp <- orient_new_axis(N, "C", a, N$k); (N$i + Cp$k) | N$k}), "(C.k|N.k) + (N.i|N.k)")
  expect_equal(.pyfmt(DyadicZero() != 0), "True")
  expect_equal(.pyfmt(DyadicZero()), "0")
  expect_equal(.pyfmt(BaseDyadic(R$i, R$j) != BaseDyadic(R$j, R$i)), "True")
  expect_equal(.pyfmt(BaseDyadic(VectorZero(), R$i)), "0")
  expect_equal(.pyfmt(BaseDyadic(R$i, VectorZero()) == DyadicZero()), "True")
  expect_error(BaseDyadic(R$i, 2*R$j), "BaseDyadic cannot be composed of non-base vectors", fixed = TRUE)
  expect_equal(.pyfmt(sym_type(R$i | R$i)), "BaseDyadic")
  expect_equal(.pyfmt(sym_type(a*(R$i | R$i))), "DyadicMul")
  expect_equal(.pyfmt(base_vector(a*(R$i | R$i))), "(R.i|R.i)")
  expect_equal(.pyfmt(measure_number(a*(R$i | R$i))), "a")
  expect_equal(.pyfmt(sym_type(a*(R$i | R$i) + b*(R$i | R$j))), "DyadicAdd")
  expect_equal(.pyfmt((R$i | R$i) == outer_sym(R$i, R$i)), "True")
  expect_equal(.pyfmt((a*R$i - R$k) | (R$i + b*R$j)), "a*(R.i|R.i) + a*b*(R.i|R.j) + (-1)*(R.k|R.i) + (-b)*(R.k|R.j)")
  expect_equal(.pyfmt(outer_sym(a*R$i - R$k, R$i + b*R$j)), "a*(R.i|R.i) + a*b*(R.i|R.j) + (-1)*(R.k|R.i) + (-b)*(R.k|R.j)")
  expect_equal(.pyfmt(((a*R$i - R$k) | (R$i + b*R$j)) == a * (R$i|R$i) + (a*b) * (R$i|R$j) - (R$k|R$i) - b * (R$k|R$j)), "True")
  expect_equal(.pyfmt((R$i | R$i) * 0), "0")
