  expect_equal(.pyfmt(singular_points(ImplicitRegion(list(x, y), x^2 + y^2 - 2*x))), "EmptySet")
  expect_equal(.pyfmt(multiplicity(ImplicitRegion(list(x, y), x^2 + y^2 - 2*x), Point(1, 3))), "0")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x), x - 2))), "(x - 2,)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), Eq(y, 3*x + 2)))), "(x, 3*x + 2)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), (x - 2)^2 + (y + 3)^2 - 4), parameters = "t")), "(4*t/(t^2 + 1) + 2, 4*t^2/(t^2 + 1) - 5)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), (x - S_Half)^2 + y^2 - (S(1)/2)^2), parameters = "t")), "(t/(t^2 + 1) + 1/2, t^2/(t^2 + 1) - 1/2)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), Eq(x^2 + y^2, 2*x)), parameters = "t")), "(2*t/(t^2 + 1) + 1, 2*t^2/(t^2 + 1) - 1)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), (y - 3)^2 - 4*(x + 6)), "t")), "(-6 + 4/t^2, 3 + 4/t)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), x*y - 1), "t")), "(-1 + (t + 1)/t, t)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), x^3 + x^2 - y^2), parameters = "t")), "(t^2 - 1, t*(t^2 - 1))")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), (x^3 - y^2)), "t")), "(t^2, t^3)")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y, z), Eq(x^2 + y^2 + z^2, 2*x)), parameters = c("s", "t"))), "(2/(s^2 + t^2 + 1), 2*t/(s^2 + t^2 + 1), 2*s/(s^2 + t^2 + 1))")
  expect_equal(.pyfmt(rational_parametrization(ImplicitRegion(list(x, y), Eq(x^2 + 4*x*y + 3*y^2 + x - y + 10, 0)), "t")), "(17/2 + 4/(3*t^2 + 4*t + 1), 4*t/(3*t^2 + 4*t + 1) - 11/2)")
  expect_equal(.pyfmt(parametric_region_list(ImplicitRegion(list(x, y), x^2 + y^2 - 4))), "[ParametricRegion((2*sin(t), -2*cos(t)), (t, 0, 2*pi))]")
  expect_equal(.pyfmt(conic_coeff(list(x, y), x^2 - 4*x*y - 3*y^2 + 4*x + 8*y - 5)), "(1, -4, -3, 4, 8, -5)")
  expect_equal(.pyfmt({AA <- CoordSys3D("A"); orienter_rotation_matrix(AxisOrienter(q, AA$i + AA$j + AA$k), AA)}), "Matrix([[2*cos(q)/3 + 1/3, sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3, -sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3], [-sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3, 2*cos(q)/3 + 1/3, sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3], [sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3, -sqrt(3)*sin(q)/3 - cos(q)/3 + 1/3, 2*cos(q)/3 + 1/3]])")
  expect_equal(.pyfmt(sym_type(curl(C$x*C$i))), "VectorZero")
  expect_equal(.pyfmt(sym_type(laplacian(C$x*C$y*C$z*(i + j + k)))), "VectorZero")
  expect_equal(.pyfmt(sym_type(diff(C$x*C$i, C$y))), "VectorZero")
  expect_equal(.pyfmt(sym_type(express(VectorZero(), N))), "VectorZero")
  expect_equal(.pyfmt(.is_vec(doit(Derivative(C$x*C$i, C$y)))), "False")
  expect_equal(.pyfmt(sym_type(gradient(5))), "VectorZero")
  expect_equal(.pyfmt(.is_vec(divergence(VectorZero()))), "False")
  expect_equal(.pyfmt(sym_type(dot(C$i | C$i, VectorZero()))), "VectorZero")
  expect_equal(.pyfmt(sym_type(cross(C$i, C$i))), "VectorZero")
  expect_equal(.pyfmt(sym_type(outer_sym(C$i, VectorZero()))), "DyadicZero")
  expect_equal(.pyfmt(sym_type(i - i)), "VectorZero")
  expect_equal(.pyfmt(sym_type(simplify(sin(a)^2*i + cos(a)^2*i - i))), "VectorZero")
  expect_equal(.pyfmt(separate(C$x*C$i + C$y*C$j)), "{C: C.x*C.i + C.y*C.j}")
  expect_equal(.pyfmt(separate(C$x*C$i + N$y*N$j + C$k)), "{C: C.x*C.i + C.k, N: N.y*N.j}")
  expect_equal(.pyfmt(subs(C$x*C$i + N$y*N$j, C$x, 2)), "2*C.i + N.y*N.j")
  expect_equal(.pyfmt(diff(a*C$i + b*C$j, a)), "C.i")
  expect_equal(.pyfmt(factor((a^2 - 1)*C$i + (a^2 + 2*a + 1)*C$j)), "((a - 1)*(a + 1))*C.i + ((a + 1)^2)*C.j")
  expect_equal(.pyfmt(expand((a + 1)^2*C$i)), "(a^2 + 2*a + 1)*C.i")
})
